import re


def parse_select(sql: str) -> dict:
    pattern = r'^\s*SELECT\s+(.*?)\s+FROM\s+([\w.]+)\s*(?:WHERE\s+(.*?))?\s*$',
    match = re.match(pattern, sql, re.IGNORECASE)
    if not match:
        raise ValueError(f"Could not parse SQL statement: {sql!r}")

    columns_str = match.group(1).strip()
    table = match.group(2)
    where = match.group(3).strip() if match.group(3) is not None else None

    if columns_str == '*':
        columns = ['*']
    else:
        columns = [c.strip() for c in columns_str.split(',')]

    return {'columns': columns, 'table': table, 'where': where}

