def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0

    if begin == end:
        return 1

    queue = deque([(begin, 1)])
    visited = {begin}

    while queue:
        word, length = queue.popleft()

        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                new_word = word[:i] + c + word[i + 1:]
                if new_word in word_set and new_word not in visited:
                    if new_word == end:
                        return length + 1
                    visited.add(new_word)
                    queue.append((new_word, length + 1))

    return 0

from collections import deque


def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0
    if begin == end:
        return 1

    queue = deque([(begin, 1)])
    visited = {begin}
    alphabet = "abcdefghijklmnopqrstuvwxyz"

    while queue:
        word, level = queue.popleft()

        for i in range(len(word)):
            for c in alphabet:
                if c == word[i]:
                    continue
                new_word = word[:i] + c + word[i + 1:]
                if new_word not in word_set or new_word in visited:
                    continue
                if new_word == end:
                    return level + 1
                visited.add(new_word)
                queue.append((new_word, level + 1))

    return 0

def evaluate(expr: str) -> float:
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # --- Tokenizer ---
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit() or c == '.':
            start = i
            seen_dot = (c == '.')
            i += 1
            while i < n:
                if expr[i].isdigit():
                    i += 1
                elif expr[i] == '.' and not seen_dot:
                    seen_dot = True
                    i += 1
                else:
                    break
            tok = expr[start:i]
            if tok == '.':
                raise ValueError(f"Invalid number literal: '.'")
            tokens.append(('NUM', float(tok)))
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    # --- Recursive Descent Parser ---
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return (None, None)

    def consume():
        tok = peek()
        if tok[0] is None:
            raise ValueError("Unexpected end of expression")
        pos[0] += 1
        return tok

    def expect(kind):
        tok = consume()
        if tok[0] != kind:
            raise ValueError(f"Expected {kind!r}, got {tok[0]!r}")
        return tok[1]

    def parse_expression():
        val = parse_term()
        while peek()[0] in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                val += right
            else:
                val -= right
        return val

    def parse_term():
        val = parse_factor()
        while peek()[0] in ('*', '/'):
            op = consume()[0]
            right = parse_factor()
            if op == '*':
                val *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                val /= right
        return val

    def parse_factor():
        if peek()[0] in ('+', '-'):
            op = consume()[0]
            val = parse_factor()
            return -val if op == '-' else val
        return parse_atom()

    def parse_atom():
        kind, val = peek()
        if kind == 'NUM':
            consume()
            return val
        if kind == '(':
            consume()
            val = parse_expression()
            expect(')')
            return val
        raise ValueError(f"Unexpected token: {kind!r}")

    result = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError(f"Unexpected token after expression: {tokens[pos[0]][0]!r}")
    return result

def evaluate(expr: str) -> float:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    # --- Tokenizer ---
    def tokenize(s: str):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch in '+-*/()':
                tokens.append(ch)
                i += 1
            elif ch.isdigit() or ch == '.':
                j = i
                seen_dot = False
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    if s[j] == '.':
                        if seen_dot:
                            raise ValueError(f"Invalid number (multiple dots) at position {j}")
                        seen_dot = True
                    j += 1
                num_str = s[i:j]
                if num_str == '.':
                    raise ValueError("Invalid number (lone decimal point)")
                tokens.append(('NUM', float(num_str)))
                i = j
            else:
                raise ValueError(f"Unexpected character: {ch!r}")
        return tokens

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return tok

    # --- Recursive descent parser ---
    # expr   → term (('+' | '-') term)*
    # term   → factor (('*' | '/') factor)*
    # factor → ('+' | '-') factor | atom
    # atom   → number | '(' expr ')'

    def parse_expression():
        result = parse_term()
        while peek() == '+' or peek() == '-':
            op = consume()
            right = parse_term()
            result = result + right if op == '+' else result - right
        return result

    def parse_term():
        result = parse_factor()
        while peek() == '*' or peek() == '/':
            op = consume()
            right = parse_factor()
            result = result * right if op == '*' else result / right
        return result

    def parse_factor():
        if peek() == '+':
            consume()
            return parse_factor()
        if peek() == '-':
            consume()
            return -parse_factor()
        return parse_atom()

    def parse_atom():
        tok = consume()
        if isinstance(tok, tuple) and tok[0] == 'NUM':
            return tok[1]
        if tok == '(':
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Expected ')'")
            consume()
            return result
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError(f"Unexpected token at position {pos}: {tokens[pos]!r}")
    return result

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    m, n = len(a), len(b)

    # Build LCS DP table: dp[i][j] = LCS length of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to produce the diff
    result: list[tuple[str, str]] = []
    i, j = m, n
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            result.append((' ', a[i - 1]))
            i -= 1
            j -= 1
        elif i > 0 and j > 0:
            # Prefer insertion during backtracking (which becomes deletion-first
            # after reversal), ensuring deletions precede insertions per hunk.
            if dp[i][j - 1] >= dp[i - 1][j]:
                result.append(('+', b[j - 1]))
                j -= 1
            else:
                result.append(('-', a[i - 1]))
                i -= 1
        elif i > 0:
            result.append(('-', a[i - 1]))
            i -= 1
        else:
            result.append(('+', b[j - 1]))
            j -= 1

    result.reverse()
    return result

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
